sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {
        current.assignment_group = "14c889db47a0be106c0c59f4f16d43f7"; //Logística paquetizados
        if (current.service_acronym == 7) { //Si es servicio especial(SSE-) se marca true
            current.special_packaged = true;
        } else {
            current.special_packaged = false;
        }
        var sysIdRegex = /^[0-9a-f]{32}$/; // patrón sys_id para validar si ya esta referenciado
        if (!gs.nil(current.customer_name) && !sysIdRegex.test(current.customer_name)) {
            var cn = new GlideRecord('customer_account');
            cn.addQuery('name', 'CONTAINS', current.customer_name);
            cn.query();
            if (cn.next()) {
                current.customer_name = cn.getUniqueValue();
            } else {
                gs.addErrorMessage('No se encontró registro para el cliente ' + current.customer_name);
                gs.error('No se encontró registro para el cliente ' + current.customer_name);
                current.customer_name = null;
                current.setAbortAction(true);
            }
        }
        if (!gs.nil(current.site_name) && !sysIdRegex.test(current.site_name)) {
            var sn = new GlideRecord('cmn_location');
            sn.addQuery('name', 'CONTAINS', current.site_name);
            sn.query();
            if (sn.next()) {
                current.site_name = sn.getUniqueValue();
            } else {
                gs.addErrorMessage('No se encontró registro para sitio ' + current.site_name);
                gs.error('No se encontró registro para sitio ' + current.site_name);
                current.site_name = null;
                current.setAbortAction(true);
            }
        }
    } catch (error) {
        gs.error('Error al validar campos de OS ' + current.number + ", error: " + error);
    }

})(current, previous);
